"use client";

import { Settings, Zap } from "lucide-react";
import { motion } from "motion/react";
import { cn } from "@/lib/utils";
import { VELOCITY_THRESHOLDS } from "./constants";
import { useVelocityState } from "./VelocityContext";

export function FlightControl() {
  const {
    velocity,
    manualVelocity,
    setManualVelocity,
    readingState,
    reducedMotion,
  } = useVelocityState();

  const isManual = manualVelocity !== null;
  const fillPercent = Math.min(
    (velocity / VELOCITY_THRESHOLDS.NORMALIZATION_MAX) * 100,
    100
  );

  return (
    <div
      aria-label="Flight Control — velocity dashboard"
      className="fixed bottom-8 left-1/2 z-100 flex w-[calc(100%-2rem)] max-w-[420px] -translate-x-1/2 items-center gap-3 rounded-2xl border border-white/10 bg-zinc-900/60 p-3 shadow-[0_20px_50px_rgba(0,0,0,0.5)] backdrop-blur-2xl sm:gap-6 sm:p-4"
      role="toolbar"
    >
      <div className="flex min-w-0 flex-1 flex-col gap-1">
        <div className="mb-1 flex justify-between font-mono text-[9px] text-zinc-500 uppercase tracking-widest sm:text-[10px]">
          <span className="flex items-center gap-1.5 truncate sm:gap-2">
            <Zap
              className={cn(
                isManual ? "animate-pulse text-primary" : "text-primary/50"
              )}
              size={10}
            />
            <span className="hidden min-[400px]:inline">Velocity Vector</span>
            <span className="min-[400px]:hidden">VEL</span>
          </span>
          <span
            className={cn(
              "whitespace-nowrap",
              readingState === "skim"
                ? "font-bold text-primary"
                : "text-zinc-400"
            )}
          >
            {Math.round(velocity)} PX/S
          </span>
        </div>

        <div className="group/slider relative flex h-8 w-full items-center">
          <div className="relative h-1.5 w-full overflow-hidden rounded-full bg-zinc-800/50">
            <motion.div
              animate={{
                width: `${fillPercent}%`,
                backgroundColor: isManual
                  ? "hsl(var(--primary))"
                  : "hsl(var(--foreground))",
              }}
              className="absolute inset-y-0 left-0"
              transition={
                reducedMotion
                  ? { duration: 0 }
                  : { type: "spring", damping: 30, stiffness: 200 }
              }
            />
          </div>

          <input
            aria-label="Velocity control"
            aria-valuetext={`${Math.round(velocity)} pixels per second`}
            className="absolute inset-0 z-20 h-full w-full cursor-pointer opacity-0"
            max={VELOCITY_THRESHOLDS.NORMALIZATION_MAX}
            min="0"
            onChange={(e) => setManualVelocity(Number(e.target.value))}
            type="range"
            value={velocity}
          />

          <motion.div
            animate={{
              left: `${fillPercent}%`,
              x: "-50%",
              scale: isManual ? 1.2 : 0.8,
              opacity: isManual ? 1 : 0,
            }}
            className="pointer-events-none absolute top-1/2 z-10 h-3.5 w-3.5 -translate-y-1/2 rounded-full bg-white shadow-[0_0_15px_rgba(255,255,255,0.5)]"
            transition={
              reducedMotion
                ? { duration: 0 }
                : { type: "spring", damping: 25, stiffness: 300 }
            }
          />

          {!isManual && (
            <div
              className="pointer-events-none absolute top-1/2 h-3 w-3 -translate-y-1/2 rounded-full border-2 border-white/20 opacity-0 transition-opacity group-hover/slider:opacity-100"
              style={{
                left: `${fillPercent}%`,
                transform: "translate(-50%, -50%)",
              }}
            />
          )}
        </div>
      </div>

      <div className="h-10 w-px bg-white/10" />

      <div className="flex items-center gap-4">
        <button
          aria-label={
            isManual
              ? "Switch to auto-scroll velocity"
              : "Switch to manual override"
          }
          className={cn(
            "rounded-xl p-3 transition-all duration-300",
            isManual
              ? "bg-primary text-black shadow-[0_0_20px_hsl(var(--primary)/0.4)]"
              : "bg-white/5 text-zinc-400 hover:bg-white/10"
          )}
          onClick={() => setManualVelocity(isManual ? null : velocity)}
          type="button"
        >
          <motion.div
            animate={
              !reducedMotion && isManual ? { rotate: 360 } : { rotate: 0 }
            }
            transition={
              isManual
                ? {
                    duration: 4,
                    repeat: Number.POSITIVE_INFINITY,
                    ease: "linear",
                  }
                : { duration: 0.3 }
            }
          >
            <Settings size={18} />
          </motion.div>
        </button>
        <div className="flex min-w-[80px] flex-col items-start">
          <div className="font-mono text-[10px] text-zinc-500 uppercase tracking-tighter">
            System Phase
          </div>
          <div
            className={cn(
              "font-black text-sm uppercase leading-none tracking-tighter",
              readingState === "skim" ? "text-primary" : "text-blue-400"
            )}
          >
            {readingState}
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * Velocity-Responsive Design (VRD) Constants
 */

export const VELOCITY_THRESHOLDS = {
  VELOCITY_SCALE: 10, // Lenis velocity amplifier (lerp-smoothed → display-scale)
  SKIM_ENTER: 500, // Transition to skim mode at 500 (scaled) px/s
  SKIM_EXIT: 400, // Must drop below 400 (scaled) px/s to trigger exit countdown
  IS_SCROLLING: 10,
  NORMALIZATION_MAX: 3000, // Visual effects scale relative to this peak
};

export const TIMINGS = {
  SKIM_EXIT_DELAY: 2500, // Duration to stay in skim mode after speed drops
  SCROLL_LOCK_DURATION: 700, // Duration to lock velocity tracking during programmatic scrolls (covers spring animation)
};

export const SPRING_CONFIGS = {
  TRANSITION: {
    duration: 0.6,
    type: "spring" as const,
    damping: 30,
    stiffness: 100,
  },
  IMAGE_TRANSITION: {
    type: "spring" as const,
    damping: 30,
    stiffness: 150,
  },
  IMAGE_MOTION: {
    type: "spring" as const,
    damping: 25,
    stiffness: 120,
    mass: 0.5,
  },
};

"use client";

import type Lenis from "lenis";
import { useReducedMotion } from "motion/react";
import type React from "react";
import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
} from "react";
import { useDevControls } from "@/hooks/useDevControls";
import { TIMINGS, VELOCITY_THRESHOLDS } from "./constants";
import { useVelocityEngine } from "./hooks/useVelocityEngine";

type ReadingState = "detailed" | "skim";

interface VelocityContextType {
  isScrolling: boolean;
  lockVelocity: () => void;
  manualVelocity: number | null;
  normalizedVelocity: number;
  readingState: ReadingState;
  reducedMotion: boolean;
  setManualVelocity: (v: number | null) => void;
  velocity: number;
}

const VelocityContext = createContext<VelocityContextType | undefined>(
  undefined
);

interface VelocityProviderProps {
  children: React.ReactNode;
  lenis: Lenis | null;
}

export function VelocityProvider({ children, lenis }: VelocityProviderProps) {
  const reducedMotion = useReducedMotion() ?? false;
  const [manualVelocity, setManualVelocityRaw] = useState<number | null>(null);

  const config = useDevControls("Velocity Thresholds", {
    velocityScale: {
      value: VELOCITY_THRESHOLDS.VELOCITY_SCALE,
      min: 1,
      max: 50,
      step: 1,
    },
    skimEnter: {
      value: VELOCITY_THRESHOLDS.SKIM_ENTER,
      min: 500,
      max: 5000,
      step: 100,
    },
    skimExit: {
      value: VELOCITY_THRESHOLDS.SKIM_EXIT,
      min: 50,
      max: 2000,
      step: 50,
    },
    skimExitDelay: {
      value: TIMINGS.SKIM_EXIT_DELAY,
      min: 500,
      max: 5000,
      step: 100,
    },
    normalizationMax: {
      value: VELOCITY_THRESHOLDS.NORMALIZATION_MAX,
      min: 1000,
      max: 6000,
      step: 100,
    },
  });

  const engine = useVelocityEngine(lenis, config, {
    reducedMotion,
    manualVelocity,
  });

  const setManualVelocity = useCallback(
    (v: number | null) => setManualVelocityRaw(v),
    []
  );

  const value = useMemo<VelocityContextType>(
    () => ({
      ...engine,
      manualVelocity,
      reducedMotion,
      setManualVelocity,
    }),
    [engine, manualVelocity, reducedMotion, setManualVelocity]
  );

  return (
    <VelocityContext.Provider value={value}>
      {children}
    </VelocityContext.Provider>
  );
}

export function useVelocityState() {
  const context = useContext(VelocityContext);
  if (context === undefined) {
    throw new Error("useVelocityState must be used within a VelocityProvider");
  }
  return context;
}

"use client";

import type Lenis from "lenis";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { TIMINGS, VELOCITY_THRESHOLDS } from "../constants";

type ReadingState = "detailed" | "skim";

export interface VelocityEngineConfig {
  normalizationMax: number;
  skimEnter: number;
  skimExit: number;
  skimExitDelay: number;
  velocityScale: number;
}

export interface VelocityEngineState {
  isScrolling: boolean;
  lockVelocity: () => void;
  normalizedVelocity: number;
  readingState: ReadingState;
  velocity: number;
}

export function useVelocityEngine(
  lenis: Lenis | null,
  config: VelocityEngineConfig,
  options: { manualVelocity: number | null; reducedMotion: boolean }
): VelocityEngineState {
  const { reducedMotion, manualVelocity } = options;

  const [scrollV, setScrollV] = useState(0);
  const [readingState, setReadingState] = useState<ReadingState>("detailed");
  const [isLocked, setIsLocked] = useState(false);

  const exitTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const idleTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const velocity = manualVelocity ?? scrollV;

  // --- Hysteresis state machine ---

  const updateReadingState = useCallback(
    (v: number) => {
      if (reducedMotion) {
        return;
      }

      if (v > config.skimEnter) {
        setReadingState("skim");
        if (exitTimerRef.current) {
          clearTimeout(exitTimerRef.current);
          exitTimerRef.current = null;
        }
      } else if (v < config.skimExit) {
        setReadingState((prev) => {
          if (prev === "skim" && !exitTimerRef.current) {
            exitTimerRef.current = setTimeout(() => {
              setReadingState("detailed");
              exitTimerRef.current = null;
            }, config.skimExitDelay);
          }
          return prev;
        });
      } else if (exitTimerRef.current) {
        clearTimeout(exitTimerRef.current);
        exitTimerRef.current = null;
      }
    },
    [reducedMotion, config.skimEnter, config.skimExit, config.skimExitDelay]
  );

  // Keep reading state in sync when driven by manual velocity (FlightControl slider)
  useEffect(() => {
    if (manualVelocity !== null) {
      updateReadingState(manualVelocity);
    }
  }, [manualVelocity, updateReadingState]);

  // --- Lenis scroll listener ---

  const onScrollRef = useRef<(l: Lenis) => void>(() => {});
  onScrollRef.current = (l: Lenis) => {
    if (isLocked || manualVelocity !== null) {
      return;
    }

    const absV = Math.floor(Math.abs(l.velocity) * config.velocityScale);
    if (absV !== scrollV) {
      setScrollV(absV);
      updateReadingState(absV);
    }

    if (l.scroll <= 0) {
      updateReadingState(0);
    }

    if (idleTimerRef.current) {
      clearTimeout(idleTimerRef.current);
    }
    idleTimerRef.current = setTimeout(() => {
      setScrollV(0);
      updateReadingState(0);
    }, 150);
  };

  useEffect(() => {
    if (!lenis) {
      return;
    }
    const handler = (l: Lenis) => onScrollRef.current(l);
    lenis.on("scroll", handler);
    return () => {
      lenis.off("scroll", handler);
      if (idleTimerRef.current) {
        clearTimeout(idleTimerRef.current);
      }
    };
  }, [lenis]);

  // --- Velocity lock (suppresses tracking during scroll stabilizer corrections) ---

  const lockVelocity = useCallback(() => {
    setIsLocked(true);
    if (exitTimerRef.current) {
      clearTimeout(exitTimerRef.current);
      exitTimerRef.current = null;
    }
    setTimeout(() => setIsLocked(false), TIMINGS.SCROLL_LOCK_DURATION + 100);
  }, []);

  // --- Derived values ---

  const normalizedVelocity = useMemo(
    () => Math.min(velocity / config.normalizationMax, 1),
    [velocity, config.normalizationMax]
  );

  const isScrolling = useMemo(
    () =>
      velocity > VELOCITY_THRESHOLDS.IS_SCROLLING || manualVelocity !== null,
    [velocity, manualVelocity]
  );

  return {
    velocity,
    normalizedVelocity,
    readingState,
    isScrolling,
    lockVelocity,
  };
}

"use client";

import type React from "react";
import { useRef } from "react";
import { useScrollStabilizer } from "./hooks/useScrollStabilizer";
import { useVelocityState } from "./VelocityContext";

interface IntelligentScrollerProps {
  children: React.ReactNode;
}

export function IntelligentScroller({ children }: IntelligentScrollerProps) {
  const { readingState, lockVelocity } = useVelocityState();
  const containerRef = useRef<HTMLDivElement>(null);

  useScrollStabilizer(containerRef, readingState, lockVelocity);

  return (
    <main
      className="relative z-10 mx-auto max-w-3xl px-6 py-24"
      ref={containerRef}
    >
      {children}
    </main>
  );
}

"use client";

import { useEffect, useLayoutEffect, useRef } from "react";

interface ScrollAnchor {
  index: number;
  viewportOffset: number;
}

const CORRECTION_FRAMES = 36; // ~600ms at 60fps, matches spring animation duration

/**
 * Tracks a visual anchor element and compensates for layout shifts
 * when the reading state changes (content morphs between detailed/skim).
 */
export function useScrollStabilizer(
  containerRef: React.RefObject<HTMLDivElement | null>,
  readingState: string,
  lockVelocity: () => void
) {
  const lastAnchorRef = useRef<ScrollAnchor | null>(null);

  useEffect(() => {
    const updateAnchor = () => {
      if (!containerRef.current) {
        return;
      }

      const children = containerRef.current.children;
      const viewportTarget = window.innerHeight * 0.4;

      let closestIndex = 0;
      let minDistance = Number.POSITIVE_INFINITY;

      for (let i = 0; i < children.length; i++) {
        const distance = Math.abs(
          children[i].getBoundingClientRect().top - viewportTarget
        );
        if (distance < minDistance) {
          minDistance = distance;
          closestIndex = i;
        }
      }

      const el = children[closestIndex];
      if (el) {
        lastAnchorRef.current = {
          index: closestIndex,
          viewportOffset: el.getBoundingClientRect().top,
        };
      }
    };

    window.addEventListener("scroll", updateAnchor, { passive: true });
    updateAnchor();
    return () => window.removeEventListener("scroll", updateAnchor);
  }, [containerRef]);

  // biome-ignore lint/correctness/useExhaustiveDependencies: readingState is a trigger -- the effect compensates for layout shifts caused by state change
  useLayoutEffect(() => {
    if (!(lastAnchorRef.current && containerRef.current)) {
      return;
    }

    const anchor = lastAnchorRef.current;
    const target = containerRef.current.children[anchor.index] as HTMLElement;
    if (!target) {
      return;
    }

    lockVelocity();

    const initialDelta =
      target.getBoundingClientRect().top - anchor.viewportOffset;
    if (Math.abs(initialDelta) > 0.5) {
      window.scrollBy({
        top: initialDelta,
        behavior: "instant" as ScrollBehavior,
      });
    }

    let frame = 0;
    let correctionRaf = 0;
    const correct = () => {
      const delta = target.getBoundingClientRect().top - anchor.viewportOffset;
      if (Math.abs(delta) > 0.5) {
        window.scrollBy({ top: delta, behavior: "instant" as ScrollBehavior });
      }
      frame++;
      if (frame < CORRECTION_FRAMES) {
        correctionRaf = requestAnimationFrame(correct);
      }
    };
    correctionRaf = requestAnimationFrame(correct);

    return () => cancelAnimationFrame(correctionRaf);
  }, [readingState, lockVelocity, containerRef]);
}

"use client";

import { useCallback, useEffect, useRef } from "react";
import { useTempus } from "tempus/react";
import { useVelocityState } from "./VelocityContext";

interface Particle {
  length: number;
  speed: number;
  x: number;
  y: number;
}

const PARTICLE_COUNT = 40;

export function SpeedLines() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ctxRef = useRef<CanvasRenderingContext2D | null>(null);
  const { normalizedVelocity, reducedMotion } = useVelocityState();
  const velocityRef = useRef(normalizedVelocity);
  const particlesRef = useRef<Particle[]>([]);
  const sizeRef = useRef({ w: 0, h: 0 });

  useEffect(() => {
    velocityRef.current = normalizedVelocity;
  }, [normalizedVelocity]);

  const resize = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }

    const dpr = window.devicePixelRatio || 1;
    const w = window.innerWidth;
    const h = window.innerHeight;

    canvas.width = w * dpr;
    canvas.height = h * dpr;
    canvas.style.width = `${w}px`;
    canvas.style.height = `${h}px`;

    const ctx = canvas.getContext("2d");
    if (ctx) {
      ctx.scale(dpr, dpr);
      ctxRef.current = ctx;
    }

    sizeRef.current = { w, h };
  }, []);

  useEffect(() => {
    if (reducedMotion) {
      return;
    }

    resize();

    if (particlesRef.current.length === 0) {
      const { w, h } = sizeRef.current;
      for (let i = 0; i < PARTICLE_COUNT; i++) {
        particlesRef.current.push({
          x: Math.random() * w,
          y: Math.random() * h,
          length: Math.random() * 100 + 50,
          speed: Math.random() * 5 + 2,
        });
      }
    }

    window.addEventListener("resize", resize);
    return () => window.removeEventListener("resize", resize);
  }, [reducedMotion, resize]);

  useTempus(
    () => {
      if (reducedMotion) {
        return;
      }

      const ctx = ctxRef.current;
      if (!ctx) {
        return;
      }

      const { w, h } = sizeRef.current;
      const v = velocityRef.current;
      ctx.clearRect(0, 0, w, h);

      if (v < 0.1) {
        return;
      }

      const centerX = w / 2;
      const centerY = h / 2;
      const halfW = w / 2;

      for (const p of particlesRef.current) {
        const dx = p.x - centerX;
        const dy = p.y - centerY;
        const angle = Math.atan2(dy, dx);
        const distance = Math.sqrt(dx * dx + dy * dy);
        const distRatio = distance / halfW;

        ctx.strokeStyle = `rgba(255, 255, 255, ${v * 0.5 * distRatio})`;
        ctx.lineWidth = 0.5 + v * 1.5;

        ctx.beginPath();
        ctx.moveTo(p.x, p.y);

        const lineLength = p.length * v * distRatio;
        ctx.lineTo(
          p.x + Math.cos(angle) * lineLength,
          p.y + Math.sin(angle) * lineLength
        );
        ctx.stroke();

        const speed = p.speed * v * 20;
        p.x += Math.cos(angle) * speed;
        p.y += Math.sin(angle) * speed;

        if (p.x < 0 || p.x > w || p.y < 0 || p.y > h) {
          const startAngle = Math.random() * Math.PI * 2;
          const startDistance = Math.random() * 200;
          p.x = centerX + Math.cos(startAngle) * startDistance;
          p.y = centerY + Math.sin(startAngle) * startDistance;
          p.length = Math.random() * 80 + 20;
        }
      }
    },
    { priority: 2 }
  );

  return (
    <canvas
      className="pointer-events-none fixed inset-0 z-0 opacity-40 mix-blend-screen"
      ref={canvasRef}
    />
  );
}

"use client";

import { FileCode, Terminal } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import { cn } from "@/lib/utils";
import { SPRING_CONFIGS } from "./constants";
import { useVelocityState } from "./VelocityContext";

interface VelocityCodeBlockProps {
  code: string;
  filename: string;
  language: string;
}

export function VelocityCodeBlock({
  filename,
  language,
  code,
}: VelocityCodeBlockProps) {
  const { readingState, reducedMotion } = useVelocityState();
  const isSkim = readingState === "skim";

  return (
    <motion.div
      animate={{
        scale: isSkim ? 0.98 : 1,
        opacity: isSkim ? 0.8 : 1,
      }}
      className={cn(
        "my-8 overflow-hidden rounded-lg border",
        isSkim
          ? "border-primary/20 bg-primary/5"
          : "border-white/10 bg-zinc-950"
      )}
      layout={!reducedMotion}
      transition={reducedMotion ? { duration: 0 } : SPRING_CONFIGS.TRANSITION}
    >
      <div className="flex items-center justify-between border-white/5 border-b bg-white/5 px-4 py-2">
        <div className="flex items-center gap-2">
          <FileCode className="text-primary" size={14} />
          <span className="font-mono text-muted-foreground text-xs">
            {filename}
          </span>
        </div>
        <span className="text-[10px] text-muted-foreground/50 uppercase tracking-widest">
          {language}
        </span>
      </div>

      <AnimatePresence initial={false} mode="popLayout">
        {isSkim ? (
          <motion.div
            animate={{ opacity: 1, scale: 1 }}
            className="relative flex h-10 items-center gap-3 overflow-hidden px-4 text-primary/60 text-sm italic"
            exit={{ opacity: 0, scale: 0.98 }}
            initial={{ opacity: 0, scale: 1.02 }}
            key="skim"
            transition={reducedMotion ? { duration: 0 } : undefined}
          >
            {!reducedMotion && (
              <motion.div
                animate={{ x: ["-100%", "200%"] }}
                className="pointer-events-none absolute inset-0 bg-linear-to-r from-transparent via-primary/5 to-transparent"
                transition={{
                  duration: 1.5,
                  repeat: Number.POSITIVE_INFINITY,
                  ease: "linear",
                }}
              />
            )}
            <Terminal size={14} />
            <span>Implementation details collapsed for speed...</span>
          </motion.div>
        ) : (
          <motion.div
            animate={{ opacity: 1, scale: 1 }}
            className="overflow-x-auto p-4"
            exit={{ opacity: 0, scale: 1.02 }}
            initial={{ opacity: 0, scale: 0.98 }}
            key="detailed"
            transition={reducedMotion ? { duration: 0 } : undefined}
          >
            <pre className="font-mono text-sm text-zinc-300">
              <code>{code}</code>
            </pre>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

"use client";

import { motion } from "motion/react";
import { SPRING_CONFIGS } from "./constants";
import { useVelocityState } from "./VelocityContext";

interface VelocityImageProps {
  alt: string;
  src: string;
}

export function VelocityImage({ src, alt }: VelocityImageProps) {
  const { normalizedVelocity, readingState, reducedMotion } =
    useVelocityState();

  const isSkim = readingState === "skim";

  return (
    <div
      className="grid transition-[grid-template-rows] duration-500 ease-out"
      style={{ gridTemplateRows: isSkim ? "1fr" : "0fr" }}
    >
      <div className="overflow-hidden">
        <motion.div
          animate={{
            opacity: isSkim ? 1 : 0,
            scale: isSkim ? 1 : 0.95,
            y: reducedMotion ? 0 : isSkim ? -normalizedVelocity * 20 : 0,
          }}
          className="my-12 aspect-video w-full overflow-hidden rounded-2xl border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.5)]"
          transition={
            reducedMotion ? { duration: 0 } : SPRING_CONFIGS.IMAGE_TRANSITION
          }
        >
          <img
            alt={alt}
            className="block h-full w-full object-cover"
            src={src}
          />

          {!reducedMotion && normalizedVelocity > 0.4 && (
            <div
              className="pointer-events-none absolute inset-0 bg-white/5 mix-blend-overlay"
              style={{ opacity: (normalizedVelocity - 0.4) * 1.5 }}
            />
          )}
        </motion.div>
      </div>
    </div>
  );
}

